theorem.content:
\label{Theorem_formula_ker_ITT_intro}
	Let $\Delta$ be an $n$-dimensional lattice polytope with $\Int(\Delta) \cap M \nsubseteq \textrm{ hyperplane}$. Then
	\begin{align}
		\ker(d \mathcal{P}_{B,f}^k) \overset{\mod \Lie(T)}{=}&  \Big\langle g_{\Gamma}(f) \cdot x^w \in L(\Delta)/\mathbb{C} \cdot f \quad \mid \quad  \Gamma \leq \Delta \textrm{ a facet}, \nonumber  \\
		& w + v \in \big( \Int((k+1) \cdot \Delta) \cup \Int((k+1) \cdot \Gamma) \big) \cap M, \nonumber \quad \\ 
		& \forall \, v \in \Int(k \cdot \Delta) \cap M \Big\rangle. \nonumber
	\end{align}
	where $\langle \rangle$ denotes the span as $\mathbb{C}$-vector space.

ref_dict.proposition_Hodge_comp_Z_f_arbitary_k_di:
\begin{proposition} \label{proposition_Hodge_comp_Z_f_arbitary_k_dimensions_and_basis}
	Let $\Delta$ be an $n$-dimensional lattice polytope with $l^*(\Delta) > 0$ and a given $f$. Given $\Gamma_1,...,\Gamma_{n+1} \leq \Delta$ with $n_{\Gamma_1},...,n_{\Gamma_{n+1}}$ affine linear independent. Then 
	\begin{align*}
		R_{Int,f}^k = L^*(k \cdot \Delta) / U_{f,k} \quad k=1,...,n+1
	\end{align*}
	where $U_{f,k}$ denotes the vector space over $\mathbb{C}$ spanned by
	\begin{align}
		& g_{\Gamma_i}(f) \cdot x^v \quad i=1,...,n+1, \quad v \in \Int((k-1) \cdot \Delta) \cap M \label{formula_relation_g_Gamma_i_f_the_1}	 \\
		& g_{\Gamma}(f) \cdot x^v \quad \Gamma \leq \Delta, \quad \quad \quad \quad \, \, \, \, v \in \Int((k-1) \cdot \Gamma) \cap M \label{formula_relation_g_Gamma_i_f_the_2}
	\end{align}
	If $k=2$ these polynomials are linearly independent.
\end{proposition}

ref_dict.Theorem_formula_ker_ITT:
\begin{theorem} \label{Theorem_formula_ker_ITT}
	Let $\Delta$ be an $n$-dimensional lattice polytope with $\Int(\Delta) \cap M \nsubseteq \textrm{ hyperplane}$. Then
	\begin{align} \label{general_formula_for_ker_DP_MDelta_handable}
		\ker(d \phi_{f}^k) =&  \Big\langle g_{\Gamma}(f) \cdot x^w \in R_f^1 \mid \Gamma \leq \Delta \textrm{ a facet}, \nonumber  \\
		& w + v \in \big( \Int((k+1) \cdot \Delta) \cup \Int((k+1) \cdot \Gamma) \big) \cap M, \nonumber \quad \\ 
		& \forall \, v \in \Int(k \cdot \Delta) \cap M \Big\rangle. \nonumber
	\end{align}
\end{theorem}

ref_dict.corollary_conjecture_ker_dphi_f_k:
\begin{corollar} \label{corollary_conjecture_ker_dphi_f_k}
	\normalfont
	Under the assumption of theorem (\ref{Theorem_formula_ker_ITT}) we have
	\begin{align*}
		\ker(d \phi_{f}) = \ker(d \phi_{f}^1).
	\end{align*}
\end{corollar}

ref_dict.definition_R_Int_f_k:
\begin{definition} \label{definition_R_Int_f_k}
	We denote the homogeneous ideal $R_f \cap S_{\Delta}^*$ of $R_{f}$ by $R_{Int,f}$ and its k-th homogeneous component by $R_{Int,f}^k$. We call $R_{Int,f}$ the \textit{interior $R_{f}$-module}.
\end{definition}

