\begin{conjecture}[Dean's conjecture]\label{conj:Dean}
    For every integer $k \geq 3$, every graph with minimum degree at least $k$ contains a cycle of length divisible by $k$.
\end{conjecture}

\vskip -1mm

Observe that every graph in $\{K_{k+1}, K_{k,k}\} \cup \mathcal{H}_k$ contains cycles of all even lengths modulo~$k$, with the sole exception of length $2 \pmod k$.
Consequently, we obtain the following immediate corollary, 
which resolves Conjecture~\ref{conj:Dean} affirmatively for all $k \ge 6$.\footnote{The case $k=5$ requires separate arguments and we will address this special case in forthcoming work.}

\begin{thm}\label{thm:exist admis}
 Let $k\ge 7$ and let $G$ be a graph with minimum degree at least $k$.
 Then $G$ contains $k$ admissible cycles, unless every end-block of $G$ is isomorphic to a graph in $\{K_{k+1}, K_{k,k}\}\cup \mathcal{H}_{k}$.
\end{thm}

\begin{thm}\label{thm:weak graph}
Let $k\geq 6$ be an integer. If $G$ is a $k$-weak graph not isomorphic to any graph in $\{K_{k+1}, K_{k,k}\}\cup \mathcal{H}_{k}$, then $G$ contains a cycle of length $r\pmod k$ for every even integer $r$.
\end{thm}

\begin{proof}[\bf{Proof of Theorem~\ref{main 1} (assuming Theorem~\ref{thm:weak graph}).}]
It suffices to establish the following stability result for 2-connected graphs: for $k\geq 6$, every 2-connected graph $G$ with $\delta_2(G) \ge k$ contains a cycle of length $r \pmod k$ for every even integer $r$, unless $G$ is isomorphic to a graph in $\{K_{k+1}, K_{k,k}\}\cup \mathcal{H}_{k}$.
Observe that every graph in $\{K_{k+1}, K_{k,k}\}\cup \mathcal{H}_{k}$ contains cycles of all even lengths modulo $k$ with the only exception of $2 \pmod k$. 
Thus, Theorem~\ref{main 1} follows directly by applying this result to each end-block of the graph (since every end-block $B$ of a graph with $\delta(G) \ge k$ satisfies $\delta_2(B) \ge k$).

\begin{thm}\label{main}
 Let $k\ge 6$ be an integer, and let $G^\star$ be a $k$-weak graph not isomorphic to $K_{k+1}$. If $G$ is non-bipartite, then $G^\star$ contains a cycle of length $r\pmod k$ for every even integer $r$.
\end{thm}

The following lemma characterizes the set of path lengths $\Pset_{u,v}^{T^*}$.
\begin{lem}\label{lem:Q-admis}
 Let $u_1, u_2$ be two distinct vertices in $V(G-T^*)$ with positive degrees $d_1:=\deg_{T^*}(u_1)$ and $d_2:=\deg_{T^*}(u_2)$. Then one of the following statements holds:
 \begin{itemize}
 \item[(1)] $\mathcal{P}_{u_1,u_2}^{T^*}$ contains at least $\min\{d_1+d_2-1,m\}$ admissible paths.
 \item[(2)] $\Pset_{u_1,u_2}^{T^*} \supseteq \{2\} \cup \{2+d, 4+d, \dots, 2m+2-d\}$ for some even $d \leq \max\{2, 2m/\max\{d_1,d_2\}, \\m-d_1-d_2+3\}$.
 \end{itemize}
\end{lem}

Using an argument analogous to Lemma~\ref{lem: B}, we deduce that $(u,v)$ is $(k-d_{\min})$-valid.
 In fact, the proof of Lemma~\ref{lem: B} relied on the fact that $\deg_{T^*}(w) \le \deg_{T^*}(u)$ for every $w\in V(B_M)\setminus\big(\{u\}\cup \mathrm{Cut}(B_M)\big)$. 
 Here, by the maximality of $\deg_{T^*}(v)$, every $w\in V(B_M)\setminus\big(\{u\}\cup \mathrm{Cut}(B_M)\big)$ satisfies $\deg_{T^*}(w) \le \deg_{T^*}(v)$, and thus $\deg_{T^*}(w) \le d_{\min}$.
 Substituting this stronger inequality into the proof of Lemma~\ref{lem: B} confirms that $(u, v)$ is $(k-d_{\min})$-valid.
 By Observation~\ref{obs:valid}, $\mathcal{P}^M_{u,v}$ contains $k-d_{\min}-1$ admissible paths.
 Let $\Pset_1$ denote the set of lengths of these admissible
 paths.
 According to Lemma~\ref{lem:Q-admis}, $\Pset^{T^*}_{u,v}$ contains a subset $\Pset_2$ with one of the following forms:
\begin{itemize}
 \item An admissible set of size at least $\min\{d_{\min}+d_{\max}-1,m\}$;
 \item $\{2\}\cup\{2+d,4+d,\cdots,2m+2-d\}$ for some even $d\leq\max\{2,2m/d_{\max},m-d_{\min}-d_{\max}+3\}$.
\end{itemize}
We verify that $\Pset_1+\Pset_2$ is an admissible set of size at least $k$.
If $\Pset_2$ is of the former case, since $3\le d_{\max}\le m-2$, the sum $\Pset_1+\Pset_2$ is an admissible set of length at least $(k-d_{\min}-1)+\min\{d_{\min}+d_{\max}-1,m\}-1\geq k$.
In the latter case, the condition for $\Pset_1+\Pset_2$ to form an admissible set is equivalent to:
\begin{align*}
 d\leq \max\{\Pset_{1}\}-\min\{\Pset_{1}\}+2\nonumber
 \iff d\leq 2(k-d_{\min}-1)\nonumber
\end{align*}
This is guaranteed by the following strict inequality, since $d$ is even. 
\begin{align*}
 &d\leq \max\{2,2m/d_{\max},m-d_{\min}-d_{\max}+3\}
 \overset{\text{($\ast$)}}{<}2(m-d_{\min})\le 2(k-d_{\min}),
\end{align*}
where $(\ast)$ is implied by the following three inequalities (as $m\geq 5$):
\begin{align*}
 2(m-d_{\min})&\geq 4>2,\\ 
 2(m-d_{\min})&\geq 2(m-d_{\max})>2m/d_{\max}, ~~~\mbox{and}\\
 2(m-d_{\min})&>m-2d_{\min}+3\geq m-d_{\min}-d_{\max}+3.
\end{align*}
Therefore, $\Pset_1+\Pset_2$ is an admissible set with minimum element $\min\{\Pset_1\}+2$ and maximum element $\max\{\Pset_1\}+\max\{\Pset_2\}$, thus has size $$\frac{\max\{\Pset_1\}-\min\{\Pset_1\}+\max\{\Pset_2\}}{2}=k+m-d_{\min}-d/2-1.$$
Note that $k+m-d_{\min}-d/2-1\geq k$ is equivalent to $d\leq 2(m-d_{\min}-1)$, which we have already established via inequality $(\ast)$.
Hence, $\Pset_1+\Pset_2$ is an admissible set of size at least $k$, and the union of paths in $\mathcal{P}^M_{u,v}$ and $\mathcal{P}^{T^*}_{u,v}$ produces $k$ admissible cycles in $G$.
This completes the proof of Lemma~\ref{lem:one comp deg}.
\end{proof}

