theorem.content:
\label{thm:main}
    There exists a sequence of compact hyperbolic $3$-manifolds $M_n$ with totally geodesic boundary such that the boundary cone-offs $\coneoff M_n$ satisfy the following:
\begin{enumerate}
    \item \label{item:negative} $\coneoff M_n$ is a closed negatively curved $3$-pseudomanifold.
    \item \label{item:T} $\pi_1(\coneoff M_n)$ contains an infinite quasiconvex subgroup with property (T).
    \item \label{item:char} The genus of the components of $\partial M_n$ and the Euler characteristic of $\coneoff M_n$ both go to infinity with $n$.
\end{enumerate}

ref_dict.cor:main:
\begin{corollary}\label{cor:main}
    In the same setting as Theorem~\ref{thm:main}, we have the following.
\begin{enumerate}
    \item  \label{item:notcubulable} $\pi_1(\coneoff M_n)$  does not act properly by cubical isometries on a  $\CAT 0$ cube complex. In particular, it is not cubulable.

    \item \label{item:notHaagerup} $\pi_1(\coneoff M_n)$ does not have the Haagerup property. In particular, it does not act properly by isometries on a real or complex hyperbolic space.

    \item \label{item:notRFRS} $\pi_1(\coneoff M_n)$ is not virtually RFRS.
\end{enumerate}
\end{corollary}

