\begin{theorem} \label{thm-asymptotics}
For $s\in(0,1)\setminus\mathbb{N}$, there holds that
\begin{itemize}
\item For $n\geq 3$ odd,
\begin{equation}\label{G1}
 G_s(\rho)=\alpha_\gamma \left(\frac{\partial_\rho}{\sinh\rho}\right)^\frac{n-1}{2}\rho^{-\frac{1}{2}+s}K_{-\frac{1}{2}+s}\left(\tfrac{n-1}{2} \rho\right),\end{equation}

\textbf{Theorem.} \textit{Let $0<\lambda<n$ and $p=\frac{2n}{2n-\lambda}$. Then for $f,g\in L^p(\bn)$,}
\begin{equation}\label{HLS}
 \left|\int_{\bn}\int_{\bn}\frac{f(x)g(y)}{(2\sinh (\frac{\rho(x,y)}{2}))^\lambda}dV_xdV_y\right|\leq C_{n,\lambda}\|f\|_p\|g\|_p,
\end{equation}
\textit{where $\rho(x,y)$ denotes the geodesic distance between $x$ and $y$ and }
\begin{equation*}
 C_{n,\lambda}=\pi^{\lambda/2}\frac{\Gamma(\frac{n}{2}-\frac{\lambda}{2})}{\Gamma(n-\frac{\lambda}{2})}\left(\frac{\Gamma(\frac{n}{2})}{\Gamma(n)}\right)^{-1+\frac{\lambda}{n}}
\end{equation*}
\textit{is the best constant for the classical Hardy-Littlewood-Sobolev constant on $\mathbb{R}^n$.
Furthermore, the constant $C_{n,\lambda}$ is sharp and there is no nonzero extremal function for the inequality (\ref{HLS}).}

To start with, we show that the differential equation \eqref{main_equation_1} is equivalent to an integral equation.
\begin{proposition}\label{DE=IE}
Let $s\in(0,1), u\in L^q_{\mathrm{loc}}(\mathbb{H}^n), q>p$.
Then the weak solution to 
\begin{equation}\label{diff_eq}
 (-\Delta_{\mathbb{H}^n})^s u = u^p 
\end{equation}
satisfies the integral equation
\begin{equation}\label{int_eq}
 u(x) = \int_{\mathbb{H}^n} \mathcal K_s(\rho(x,y)) u(y)^p dV_y,
\end{equation}
where $\mathcal K_s(\rho)$ is the fractional kernel on $\mathbb{H}^n$ defined in Section \eqref{kernel}.
Conversely, if $u$ solves the integral equation \eqref{int_eq}, then $u$ is a solution of the \eqref{diff_eq}.
\end{proposition}

\begin{proof}
By Helgason-Fourier transform, we have for any $\varphi\in C^\infty_c(\hn)$:
\begin{align*}
 \widehat{(-\Delta_{\mathbb{H}^n})^s \varphi}(\lambda,\theta) &= \left(\lambda^2 + \tfrac{(n-1)^2}{4}\right)^s \hat{\varphi}(\lambda,\theta),
\end{align*}
and 
\begin{align}\label{test_laplacian}
 (-\Delta_{\mathbb H^n})^s\varphi(x)=\int_{-\infty}^\infty\int_{\mathbb S^{n-1}}
\Bigl(\lambda^2+\frac{(n-1)^2}{4}\Bigr)^s\widehat{\varphi}(\lambda,\theta)
\,e_{\lambda,\theta}(x)
\,|c(\lambda)|^{-2}\,d\theta\,d\lambda.
\end{align}
Recall the definition of weak solution of \eqref{diff_eq}, we have
\begin{align*}
 \int_{\mathbb{H}^n} u(x) (-\Delta_{\mathbb{H}^n})^s \varphi(x) dV_x &= \int_{\mathbb{H}^n} u(x)^p \varphi(x) dV_x.
\end{align*}
Inserting \eqref{test_laplacian} to the left side, we obtain
\begin{align*}
 \int_{\mathbb H^n} u(x)(-\Delta_{\mathbb H^n})^s\varphi(x)\,dV_x
&=
\int_{\mathbb H^n} u(x)\int_{-\infty}^\infty \int_{\mathbb S^{n-1}}
\Bigl(\lambda^2+\tfrac{(n-1)^2}{4}\Bigr)^s
\widehat{\varphi}(\lambda,\theta)e_{\lambda,\theta}(x)
|c(\lambda)|^{-2}\,d\theta\,d\lambda
\,dV_x\\
&=
\int_{-\infty}^\infty \int_{\mathbb S^{n-1}}
\Bigl(\lambda^2+\tfrac{(n-1)^2}{4}\Bigr)^s
\widehat{\varphi}(\lambda,\theta)
\left[
\int_{\mathbb H^n}
u(x)e_{\lambda,\theta}(x)\,dV_x
\right]
|c(\lambda)|^{-2}\,d\theta\,d\lambda.
\end{align*}

For the far away part, we choose $a\in(1,\frac{q}{p})$, and let $a'$ denote the conjugate of $a$. By H\"older's inequality,
\[
\left|\int_{\mathbb H^n\setminus B_R(o)}G(\rho(x,y))u(y)^p\,dV_y\right| \leq \|G(\rho(x,\cdot))\|_{L^{a'}(\mathbb H^n\setminus B_R)}\;\|u^p\|_{L^{a}(\mathbb H^n\setminus B_R)}.
\]
$\|u^p\|_{L^{a}(\mathbb H^n\setminus B_R)}$ is clearly finite since $ap<q$. 
On the other hand, for large $R$, we have 
\[
\int_{ \mathbb H^n\setminus B_R} G(\rho(x,y))^{a'}\,dV_y
\lesssim \int_R^\infty \rho^{-1+s}e^{-a'(n-2s)\rho} e^{(n-1)\rho}\,d\rho
= \int_R^\infty \rho^{-1+s}e^{-(a'(n-2s)-(n-1))\rho}\,d\rho
\]
We are able to choose $a$ sufficiently close to $1$, so that $a'(n-2s)-(n-1)>0$. Thus, $\|G(\rho(x,\cdot))\|_{L^{a'}(\mathbb H^n\setminus B_R)}$ can be made arbitrarily small for large enough $R$. The proof is now complete.
\end{proof}
From the above estimate at infinity, the moving plane argument in the subcritical case applies here as well, and we conclude that $u$ is radially symmetric about some point in $\hn$.

Then we introduce a maximum principle for anti-symmetric functions.
\begin{theorem}
\label{MP_anti}
 Let $\Omega$ be a bounded domain in $\hn$. Assume that $u \in L^\alpha \cap C^{1,1}_{loc}(\Omega)$ and is lower semi-continuous on $\bar{\Omega}$ . If
 \begin{equation*}
 \begin{cases}
 (-\Delta_{\hn})^s u + c(x)u \geq 0, &\text{ in } \Omega,\\
 u \geq 0, &\text{ in } \Sigma,\\
 u(x) = -u(x^\lambda), &\text{ in } \Sigma,
 \end{cases}
 \end{equation*}
 where $c(x)$ is bounded from below in $\Omega$. Then 
 \begin{equation}\label{mp_anti_u}
 u \geq 0 \text{ in } \Omega.
 \end{equation}
 If $u = 0$ at some point in $\Omega$, then $u(x) = 0$ almost everywhere in $\hn$.
\end{theorem}
The next result is a maximum principle in narrow regions.
\begin{theorem}
\label{narrow_region}
 Let $U_\lambda,\, \Sigma_\lambda, x^\lambda$ be defined as in Section \ref{sec:prelim}. Assume that $u \in L^\alpha \cap C^{1,1}_{loc}(\Omega)$ and is lower semi-continuous on $\bar{\Omega}$ . If
 Let $\Omega$ be an bounded narrow region in $\Sigma_\lambda$, which is contained in $\{x\mid \lambda-l<x_1<\lambda\}$ with small $l$. Assume that $u \in L^\alpha \cap C^{1,1}_{loc}(\Omega)$ and is lower semi-continuous on $\bar{\Omega}$, which satisfies
 \begin{equation*}
 \begin{cases}
 (-\Delta_{\hn})^s u + c(x)u \geq 0, &\text{ in } \Omega,\\
 u \geq 0, &\text{ in } \Sigma_\lambda\setminus\Omega,\\
 u(\tilde{x}) = -u(x^\lambda), &\text{ in } \Sigma_\lambda.
 \end{cases}
 \end{equation*}
 If $c(x)$ is bounded from below in $\Omega$, then 
 \begin{equation}\label{narrow_u}
 u \geq 0 \text{ in } \Omega.
 \end{equation}
 Furthermore, if $u = 0$ at some point in $\Omega$, then $u(x) = 0$ almost everywhere in $\hn$.
\end{theorem}
\begin{proof}
 If \eqref{narrow_u} does not hold, then the lower semi-continuity of $u$ indicates that there exists a $x^0 \in \bar{\Omega}$ such that $u(x^0) = \min\limits_\Omega u < 0$. And one can further deduce that $x^0$ is in the interior of $\Omega$.
 Then 
 \begin{align*}
 &(-\Delta_{\hn})^s u(x^0) = C_{n,s} \, \text{P.V.} \int_{\mathbb{H}^n} (u(x^0) - u(\xi)) \, \mathcal{K}_{n,s}(d(x,\xi)) \, d\xi\\
 &= C_{n,s} \text{P.V.}\left\{\int_{\Sigma_\lambda} (u(x^0) - u(\xi)) \, \mathcal{K}_{n,s}(d(x,\xi)) \, d\xi + \int_{\Sigma^c_\lambda} (u(x^0) - u(\xi)) \, \mathcal{K}_{n,s}(d(x,\xi)) \, d\xi\right\}\\
 &= C_{n,s} \text{P.V.}\left\{\int_{\Sigma_\lambda} (u(x^0) - u(\xi)) \, \mathcal{K}_{n,s}(d(x,\xi)) \, d\xi + \int_{\Sigma_\lambda} (u(x^0) + u(\xi)) \, \mathcal{K}_{n,s}(d(x,\xi^\lambda)) \, d\xi\right\}\\
 &\leq C_{n,s} \text{P.V.}\left\{\int_{\Sigma_\lambda} (u(x^0) - u(\xi)) \, \mathcal{K}_{n,s}(d(x,\xi^\lambda)) \, d\xi + \int_{\Sigma_\lambda} (u(x^0) + u(\xi)) \, \mathcal{K}_{n,s}(d(x,\xi^\lambda)) \, d\xi\right\}\\
 &= 2C_{n,s} u(x^0) \int_{\Sigma_\lambda} \mathcal{K}_{n,s}(d(x,\xi^\lambda)) \, d\xi.
 \end{align*}
 To estimate the integral above, given that $x^0$ lies in a narrow region close to the hyperplane $\{y\mid y_1=\lambda\}$. Consider the extreme case that $x^0$ lies on the hyperplane $\{y\mid y_1=\lambda\}$, then 
 \begin{align*}
 \int_{\Sigma_\lambda} \mathcal{K}_{n,s}(d(x,\xi^\lambda)) \, d\xi &\sim \int_{\Sigma_\lambda}\rho^{-n-2s} \, d\xi=\infty,
 \end{align*}
 where $\rho=\disth(\xi,x^0)$. Then by integrating on a domain that is suﬃciently close to the hyperplane $P$, we can obtain a lower bound of the integral. Since $c(x)$ is bounded from below, we can choose $l$ small enough such that $(-\Delta_{\hn})^s u(x^0) + c(x^0)u(x^0) < 0$, which contradicts the assumption.
\end{proof}

post_theorem_intro_text:
Another key novelty of this paper is that we take advantage of the Helgason-Fourier analysis on hyperbolic spaces to establish the equivalence between the differential form \eqref{main_equation_1} and the integral form
\begin{equation}\label{main_equation_int}
  u(x) = \int_{\mathbb{H}^n} G_s(x,y) u^p(y) \, dV_y,
\end{equation}
where $G_{\mathbb{H}^n}(x,y)$ is the kernel of the fractional Laplacian on $\mathbb{H}^n$ given by 
\begin{equation}
  G_s(\rho) = \int_{-\infty}^\infty \int_{\mathbb{S}^{n-1}} \left(\lambda^2 + \tfrac{(n-1)^2}{4}\right)^{-s} \bar{h}_{\lambda,\theta}(x) h_{\lambda,\theta}(y)| c(\lambda)|^{-2}d\theta d\lambda.
\end{equation}
This equivalence plays an essential role in applying the moving plane method to prove Theorem \ref{thm1}.
The Helgason-Fourier analysis on general symmetric spaces was first developed by Helgason \cites{H-F1,H-F2}. It has been used in harmonic analysis and PDEs; see e.g. \cites{Anker-Ji, BGS15} and the references therein. In addition, the Helgason-Fourier analysis plays a key role in the establishment of higher order Hardy-Sobolev-Maz'ya's inequalities (see \cites{LY1,LY2, LY3, FLY1}). Using Fourier transform, we are able to derive the precise expression of the Green's function $G_s(\rho)$ and study its asymptotic behaviors near zero and infinity, which are the key ingredients in the moving plane method.

\begin{theorem} \label{thm-asymptotics}
For $s\in(0,1)\setminus\mathbb{N}$, there holds that
\begin{itemize}
\item For $n\geqslant 3$ odd,
\begin{equation}\label{G1}
  G_s(\rho)=\alpha_\gamma \left(\frac{\partial_\rho}{\sinh\rho}\right)^\frac{n-1}{2}\rho^{-\frac{1}{2}+s}K_{-\frac{1}{2}+s}\left(\tfrac{n-1}{2} \rho\right),\end{equation}

\item For $n\geqslant 2$ even,
\begin{equation}\label{G2}
G_s(\rho)=\alpha_\gamma
\int_\rho^\infty\frac{\sinh r}{\sqrt{\cosh r-\cosh\rho}}
\left(\frac{\partial_r}{\sinh r}\right)^\frac{n}{2}\left[r^{-\frac{1}{2}+s}K_{-\frac{1}{2}+s}\left(\tfrac{n-1}{2} r\right)\right]\, dr.
\end{equation}
\end{itemize}
Here $K_{-\frac{1}{2}+s}$ is the solution to the modified Bessel equation given in Lemma \ref{lemma-Bessel}.

Additionally, $G_s(\rho)$ has the asymptotic behavior:
\begin{itemize}
\item As $\rho\to 0$,
  \begin{equation}
    \label{asymptotics-zero}G_s(\rho)\sim \rho^{-n+2s}.
  \end{equation}

\item As $\rho\to\infty$,
  \begin{equation}\label{asymptotics-infty}
    G_s(\rho)\sim \rho^{-1+s}e^{-(n-1)\rho}.
  \end{equation}
\end{itemize}
\end{theorem}

The organization of this paper is as follows. In Section \ref{sec:prelim}, we provide some preliminaries on hyperbolic space $\mathbb{H}^n$. Section \ref{sec:frac_lap} collects some important information of the fractional Laplacians on $\mathbb{H}^n$ and their key properties. The precise expression and asymptotic behaviors of Green's function are provided. Section \ref{sec:proof} is dedicated to the proof of the main theorem. In Section \ref{sec:MP}, we extend several maximum principles to $\mathbb{H}^n$.

expanded_theorem:
\label{thm1}
Let $n \geqslant 2$, $0 < s < 1$. Suppose that $u\in L^q(\mathbb{H}^n), q>p$ is a nonnegative weak solution of
\begin{equation}\label{main_equation_1}
(-\Delta_{\hn})^s u = u^p(x), \quad x \in \hn.
\end{equation}
Then
\begin{enumerate}
  \item If $1 < p < \frac{n+2s}{n-2s}$ and $u\in L^{p+1}(\mathbb{H}^n)$ , then $u\equiv 0$. 
  \item If $p = \frac{n+2s}{n-2s}$ and $u\in L^q$, where $q>p$, then there exists a point $x_0 \in \mathbb{H}^n$ such that $u$ is radially symmetric and nondecreasing about $x_0$.
\end{enumerate}

ref_dict.cor-thm-KF:
\begin{corollary}\label{cor-thm-KF}
Let $K$ be a number field.
There exists an algebraic extension of $K$ that is Kummer-faithful and has abelian absolute Galois group.
\end{corollary}

ref_dict.thm-KF:
\begin{theorem}\label{thm-KF}
Suppose that $K$ is a number field and $e$ a positive integer. For almost all $\sigma \in G_K^e$, any finite extension of $\Kbar(\sigma)$ is both torally Kummer-faithful and AVKF, and thus, Kummer-faithful.
\end{theorem}

ref_dict.cor-continuummany:
\begin{corollary}\label{cor-continuummany}
Let $K$ be a number field.
There are continuum many algebraic extensions of $K$ up to $K$-isomorphism which are Kummer-faithful fields with abelian absolute Galois group.
\end{corollary}

