	\label{main thm}
	Suppose that the initial data satisfies $a \in H^1(\Omega)$ and $a_z: = \partial_z a \in L^3(\Omega)$, as well as the compatibility conditions: $\operatorname{div}_H \bar a = 0$, the horizontal periodicity, and $a = 0$ on $\Gamma_b$ in case of
\begin{equation} \label{eq: Dirichlet BC}
\begin{alignedat}{2}
	&\partial_z v =0, \quad w=0  &&\text{ on }\; \Gamma_u \times (0,T), \\
	&v = 0, \quad w=0 && \text{ on }\; \Gamma_b \times (0,T), \\
	&\text{$u$, $\pi$ are periodic} \qquad && \text{ on }\; \Gamma_l \times (0,T),
\end{alignedat}
\end{equation}
	Then the solution of
\begin{equation} \label{eq: PEs}
\begin{aligned}
	\partial_t v + u \cdot \nabla v - \Delta v + \nabla_H\pi &= 0 \qquad \text{ in }\; \Omega \times (0, T), \\
	\partial_z\pi & = 0  \qquad \text{ in }\; \Omega \times (0, T), \\
	\mathrm{div}\,u & = 0  \qquad \text{ in }\; \Omega \times (0, T),
\end{aligned}
\end{equation}
--
\begin{equation} \label{eq: initial condition}
	v|_{t = 0} = a \qquad \text{ in }\; \Omega \times \{0\},
\end{equation}
	with
\begin{equation} \label{eq: Neumann BC}
\begin{alignedat}{2}
	&\partial_z v =   0, \quad w=0  &&\text{ on }\; (\Gamma_u \cup \Gamma_b) \times (0,T), \\
	&\text{$u$, $\pi$ are periodic} \qquad   && \text{ on }\; \Gamma_l \times (0,T),
\end{alignedat}
\end{equation}
	or the boundary conditions above satisfies 
	\begin{equation*}
		\|v(t)\|_{H^1(\Omega)}^2 + \int_0^t \|\nabla^2 v(s)\|_{L^2(\Omega)}^2 \, ds \le B(a) e^{C \|a\|_{L^2(\Omega)}^2} \quad \forall t \in [0, T],
	\end{equation*}
	where $B(a)$ is a polynomial function of $\|a\|_{H^1(\Omega)}$ and $\|a_z\|_{L^3(\Omega)}$, and $C$ is a positive constant dependent only on $\Omega$.

