    There exists a constant $C=C(M,K) >0$, depending on the pair $(M,K)$, such that
    \begin{align*}
     \hbar (SH_M(K))\leq C\, h_{\textrm{top}}(\varphi_\alpha).
    \end{align*}
 \end{theorem}
\label{thma}
Let $(M,\omega)$ be a closed symplectic manifold and  $K \subset M$ be a Liouville domain. Assume that $(M,\omega)$ is symplectically aspherical and $(\partial K, \alpha)$ is index-bounded. Then there exists a constant $C=C(M,K) >0$, depending on the pair $(M,K)$, such that
\begin{align*}
    \hbar(SH_M(K)) \leq C \,h_{\textrm{top}}(\varphi_\alpha^1)
\end{align*}
where $\varphi_\alpha^t$ is the Reeb flow on $(\partial K, \alpha)$.

ref_dict.thm:99-percent:
\begin{theorem}[$99\%$ Characterization of $A$]\label{thm:99-percent}
Let $A \subseteq \F_p$ be a set with $|A| \gg p$, and let $(r_1, \ldots, r_k)$ be a generic tuple. If
\[
 |A^{r_1} + \cdots + A^{r_k}| 
 \le K p^{\frac{k-1}{k}}|A|^{1/k},
\]
then there exist sets $P_1, \ldots, P_k \subseteq \F_p$ such that, 
after removing $o(p)$ elements from~$A$, the following holds:
\begin{itemize}[itemsep=0.5em]
 \item $A \subseteq \sqrt[r_1]{P_1} \cap \cdots \cap \sqrt[r_k]{P_k}$;
 \item $\big|\sqrt[r_1]{P_1} \cap \cdots \cap \sqrt[r_k]{P_k}\big|
  = \frac{1 + o(1)}{p^{k-1}}|P_1|\cdots|P_k|$;
 \item $|P_1 + \cdots + P_k|
  \le (1 + o(1)) K p^{\frac{k-1}{k}}|A|^{1/k}$.
\end{itemize}
\end{theorem}

