\section{Construction of the calibration}
\label{sec:constr_cal}
The main result of this section is the following Theorem.
\begin{theorem} \label{thm:excal}
 For $n \geq 4$, consider the threshold $\bar{\lambda}(n)$ defined in \eqref{eq:def_barlambda}.
 Then, if $0<\lambda \leq \bar \lambda(n)$, there exists a vector field $Z : \Omega_{\lambda}' \cup S_{\lambda}' \to \R^{n+1}$ such that:
 \begin{itemize}
 \item[(i)]
 $Z\left( x,t \right) = Z \left(x, \lambda |x| \right)$, for all $(x,t) \in \Omega_{\lambda}' \cup S_{\lambda}'$;
 \medskip
 \item[(ii)] $|Z(x,t)| \leq 1$, for all $(x,t) \in \Omega_{\lambda}' \cup S_{\lambda}'$;
 \medskip
 \item[(iii)] $Z(x,t) = e_1$, for all $(x,t) \in \overline{H}_{\lambda} \cap (\Omega_{\lambda}' \cup S_{\lambda}')$;
 \medskip
 \item[(iv)] $Z (x,t) \in T_{(x,t)} S_{\lambda}$, for all $(x,t) \in S_{\lambda}'$;
 \medskip
 \item[(v)] $Z$ is smooth and $\div Z = 0$ in $\Omega_{\lambda}'$.
 \end{itemize}
\end{theorem}

\begin{proof}[Proof (of Theorem \ref{thm:min}).]
 Up to rescaling, we can assume $R = 1$. For $\epsilon > 0$, let
 \begin{equation*}
 A^{\epsilon} := \{ (x,t) \in \R^{n+1} \, : \, |x'| \leq \epsilon \} \qquad \text{and} \qquad \Omega_{\lambda}^{\epsilon} := \Omega_{\lambda} \setminus A^{\epsilon} .
 \end{equation*}
 We observe that, for every $\epsilon > 0$, $\Omega_{\lambda}^{\epsilon} \subset \Omega_{\lambda}'$. When $0 < \lambda \leq \bar{\lambda}(n)$, we can consider the vector field $Z : \Omega_{\lambda}' \to \R^{n+1}$ of Theorem \ref{thm:excal}. By the Divergence Theorem (see \cite{maggi2012sets}) and since $Z$ is divergence-free, we have
 \begin{equation} \label{eq:0=divZ}
 0 = \int_{(F \setminus E)\cap\Omega_{\lambda}^{\epsilon}} \div Z = \int_{\de^{\ast}((F \setminus E)\cap\Omega_{\lambda}^{\epsilon})} \left\langle Z \, , \, \nu_{(F \setminus E)\cap\Omega_{\lambda}^{\epsilon}} \right\rangle \, d \Hau^{n-1} .
 \end{equation}
 Owing to \eqref{eq:deEcapF}, there holds
 \begin{equation*}
 \de^{\ast} ((F \setminus E) \cap \Omega_{\lambda}^{\epsilon}) = \left( \Omega_{\lambda}^{\epsilon} \cap \de^{\ast}(F \setminus E) \right) \cup \left( (F \setminus E)^{(1)} \cap \de\Omega_{\lambda}^{\epsilon} \right) \cup Q\left(F \setminus E,\Omega_{\lambda}^{\epsilon}\right)^+ ,
 \end{equation*}
 and this in combination with \eqref{eq:0=divZ} and \eqref{eq:nuEcapF} ensures that
 \begin{equation} \label{eq:0=divZ_2}
 \begin{split}
 0 = \int_{(F \setminus E)\cap\Omega_{\lambda}^{\epsilon}} \div Z & = \int_{\Omega_{\lambda}^{\epsilon} \cap \de^{\ast}(F \setminus E)} \left\langle Z \, , \, \nu_{F \setminus E} \right\rangle \, d \Hau^{n-1} + \\
 & \qquad \qquad + \int_{\left( (F \setminus E)^{(1)} \cap \de\Omega_{\lambda}^{\epsilon} \right) \, \cup \, Q\left(F \setminus E,\Omega_{\lambda}^{\epsilon}\right)^+} \left\langle Z \, , \, \nu_{\Omega_{\lambda}^{\epsilon}} \right\rangle \, d \Hau^{n-1} \\
 & = (I) + (II) .
 \end{split}
 \end{equation}
 By \eqref{eq:deEsetminusF}, because $Z = e_1 = \nu_E$ on $\de^{\ast} E \cap \Omega_{\lambda} = H_{\lambda}$, one has
 \begin{equation} \label{eq:est_(I)}
 \begin{split}
 (I) & = \int_{\Omega_{\lambda}^{\epsilon} \cap E^{(0)} \cap \de^{\ast} F} \left \langle Z \, , \, \nu_{F} \right \rangle \, d \Hau^{n-1} - \int_{\Omega_{\lambda}^{\epsilon} \cap F^{(1)} \cap \de^{\ast} E} \left \langle Z \, , \, \nu_{E} \right \rangle \, d \Hau^{n-1} - \int_{\Omega_{\lambda}^{\epsilon} \, \cap \, Q(E,F)^-} \left \langle Z \, , \, \nu_{E} \right \rangle \, d \Hau^{n-1} \\[0.2cm]
 & \leq \p(F;E^{(0)} \cap \Omega_{\lambda}^{\epsilon}) - \p(E;F^{(1)} \cap \Omega_{\lambda}^{\epsilon}) \\
 & = \p(F;\bar{E}^{c} \cap \Omega_{\lambda}^{\epsilon}) - \p(E;F^{(1)} \cap \Omega_{\lambda}^{\epsilon}) .
 \end{split}
 \end{equation}
 Let us now estimate $(II)$. Because $E \difsim F \Subset B_1$, clearly $\de^{\ast} (F \setminus E) \subset B_1$ and $(F \setminus E)^{(1)} \subset B_1$. Thus, by applying \eqref{eq:deEsetminusF} to $\Omega_{\lambda}^{\epsilon} = \Omega_{\lambda} \setminus A^{\epsilon}$ and \eqref{eq:nuEsetminusF} to its normal, we have
 \begin{equation} \label{eq:est_(II)}
 \begin{split}
 |(II)| & \leq \int_{B_1 \cap \de \Omega_{\lambda}^{\epsilon}} \left| \left \langle Z \, , \, \nu_{\Omega_{\lambda}^{\epsilon}} \right \rangle \right| \, d \Hau^{n-1} \\
 & \leq \int_{B_1 \cap A^{\epsilon} \cap \de \Omega_{\lambda}} \left| \left \langle Z \, , \, \nu_{\Omega_{\lambda}} \right \rangle \right| \, d \Hau^{n-1} + \int_{B_1 \cap \Omega_{\lambda} \cap \de A^{\epsilon}} \left| \left \langle Z \, , \, \nu_{A^{\epsilon}} \right \rangle \right| \, d \Hau^{n-1} .
 \end{split}
 \end{equation}
 Now, since $Z$ is tangent to $S_{\lambda}'$, the first integral on the right hand side of \eqref{eq:est_(II)} vanishes. This implies that
 \begin{equation*}
 |(II)| \leq \Hau^{n-1}(B_1 \cap \de A^{\epsilon}) = C(n) \, \epsilon^{n-2} .
 \end{equation*}
 This in combination with \eqref{eq:0=divZ_2} and \eqref{eq:est_(I)} yields
 \begin{equation} \label{eq:sum_1_calib}
 \p(E;F^{(1)} \cap \Omega_{\lambda}^{\epsilon}) \leq \p(F;\bar E ^ c \cap \Omega_{\lambda}^{\epsilon}) + C(n) \, \epsilon^{n-2} .
 \end{equation}
 By applying the Divergence Theorem in $(E \setminus F) \cap \Omega_{\lambda}^{\epsilon}$ and arguing very similarly as above, we also obtain
 \begin{equation} \label{eq:sum_2_calib}
 \begin{split}
 \p(E;F^{(0)} \cap \Omega_{\lambda}^{\epsilon}) & \leq \p(F;E^{(1)} \cap \Omega_{\lambda}^{\epsilon}) + C(n) \, \epsilon^{n-2} \\
 & = \p(F;E \cap \Omega_{\lambda}^{\epsilon}) + C(n) \, \epsilon^{n-2}
 \end{split}
 \end{equation}
 Summing up \eqref{eq:sum_1_calib} and \eqref{eq:sum_2_calib}, noticing that
 \begin{equation*}
 \p(E;F^{(1)} \setminus B_1) = \p(E;F^{(0)} \setminus B_1) = 0 \qquad \text{and} \qquad \p(F;E \setminus B_1) = \p(F;\bar{E}^{c}\setminus B_1) = 0 ,
 \end{equation*}
 we deduce that
 \begin{equation*}
 \p(E;(F^{(0)} \cup F^{(1)}) \cap \Omega_{\lambda}^{\epsilon} \cap B_1) \leq \p(F;(\bar{E}^c \cup E) \cap \Omega_{\lambda}^{\epsilon} \cap B_1) + C(n) \, \epsilon^{n-2} .
 \end{equation*}
 By applying Federer's Theorem \cite[Theorem 16.2]{maggi2012sets}, we then get
 \begin{equation*}
 \p(E;\Omega_{\lambda}^{\epsilon} \cap B_1) \leq \p(F;\Omega_{\lambda}^{\epsilon} \cap B_1) + C(n) \, \epsilon^{n-2} .
 \end{equation*}
 Finally, passing to the limit as $\epsilon \to 0^+$ in the relation above, we obtain that $$\p(E;\Omega_{\lambda} \cap B_1) \leq \p(F;\Omega_{\lambda} \cap B_1),$$ and we conclude.
\end{proof}

