\begin{align}
		\label{eq:OK}
		\begin{cases}
			\dfrac{ \partial u }{ \partial t} = 
			-\displaystyle\frac{1}{\gamma^2}\dfrac{ \partial^{4} u}{ \partial x^{4}} -\dfrac{ \partial^{2} }{ \partial x^{2}}(u-u^3) -\sigma(u-m)
			, & (t,x) \in (0,\infty) \times (0,L), \\[2ex]
